                            os.rmdir(checkout_module_abspath)
                        except OSError as e:
                            raise OSError(
                                f"Module directory at {checkout_module_abspath} does already exist and is non-empty"
                            ) from e

                    progress.update(
                        BEGIN | CLONE,
                        0,
                        1,
                        prefix
                        + f"Cloning url '{self.url}' to '{checkout_module_abspath}' in submodule {self.name}",
                    )
                    if not dry_run:
                        if self.url.startswith("."):
                            url = urllib.parse.urljoin(self.repo.remotes.origin.url + "/", self.url)
                        else:
                            url = self.url
                        mrepo = self._clone_repo(
                            self.repo,
                            url,
                            self.path,
                            self.name,
                            n=True,
                            env=env,
                            multi_options=clone_multi_options,
                            allow_unsafe_options=allow_unsafe_options,
                            allow_unsafe_protocols=allow_unsafe_protocols,
                        )
                    progress.update(END | CLONE, 0, 1, prefix + f"Done cloning to {checkout_module_abspath}")

                    if not dry_run:
                        try:
                            mrepo = cast("Repo", mrepo)
                            remote_branch = find_first_remote_branch(mrepo.remotes, self.branch_name)
                            local_branch = mkhead(mrepo, self.branch_path)
                            local_branch.set_object(Object(mrepo, self.NULL_BIN_SHA))
                            mrepo.head.set_reference(
                                local_branch,
                                logmsg="submodule: attaching head to %s" % local_branch,
                            )
                            mrepo.head.reference.set_tracking_branch(remote_branch)
                        except (IndexError, InvalidGitRepositoryError):
                            _logger.warning("Failed to checkout tracking branch %s", self.branch_path)

                        with self.repo.config_writer() as writer:
                            writer.set_value(sm_section(self.name), "url", self.url)

            if mrepo is not None:
                is_detached = mrepo.head.is_detached

            if mrepo is not None and to_latest_revision:
                msg_base = f"Cannot update to latest revision in repository at {mrepo.working_dir} as "
                if not is_detached:
                    rref = mrepo.head.reference.tracking_branch()
                    if rref is not None:
                        rcommit = rref.commit
                        binsha = rcommit.binsha
                        hexsha = rcommit.hexsha
                    else:
                        _logger.error(
                            "%s a tracking branch was not set for local branch '%s'",
                            msg_base,
                            mrepo.head.reference,
                        )
                else:
                    _logger.error("%s there was no local tracking branch", msg_base)

            if mrepo is not None and mrepo.head.commit.binsha != binsha:
                may_reset = True
                if mrepo.head.commit.binsha != self.NULL_BIN_SHA:
                    base_commit = mrepo.merge_base(mrepo.head.commit, hexsha)
                    if len(base_commit) == 0 or (base_commit[0] is not None and base_commit[0].hexsha == hexsha):
                        if force:
                            msg = "Will force checkout or reset on local branch that is possibly in the future of"
                            msg += " the commit it will be checked out to, effectively 'forgetting' new commits"
                            _logger.debug(msg)
                        else:
                            msg = "Skipping %s on branch '%s' of submodule repo '%s' as it contains un-pushed commits"
                            msg %= (
                                is_detached and "checkout" or "reset",
                                mrepo.head,
                                mrepo,
                            )
                            _logger.info(msg)
                            may_reset = False

                if may_reset and not force and mrepo.is_dirty(index=True, working_tree=True, untracked_files=True):
                    raise RepositoryDirtyError(mrepo, "Cannot reset a dirty repository")

                progress.update(
                    BEGIN | UPDWKTREE,
                    0,
                    1,
                    prefix
                    + f"Updating working tree at {self.path} for submodule {self.name} to revision {hexsha}",
                )

                if not dry_run and may_reset:
                    if is_detached:
                        mrepo.git.checkout(hexsha, force=force)
                    else:
                        mrepo.head.reset(hexsha, index=True, working_tree=True)
                progress.update(
                    END | UPDWKTREE,
                    0,
                    1,
                    prefix + f"Done updating working tree for submodule {self.name}",
                )

        except Exception as err:
            if not keep_going:
                raise
            _logger.error(str(err))

        if recursive:
            if mrepo is not None:
                for submodule in self.iter_items(self.module()):
                    submodule.update(
                        recursive,
                        init,
                        to_latest_revision,
                        progress=progress,
                        dry_run=dry_run,
                        force=force,
                        keep_going=keep_going,
                    )

        return self

    @property
    def name(self) -> str:
        return self._name

    @classmethod
    def iter_items(
        cls,
        repo: "Repo",
        parent_commit: Union[Commit_ish, str] = "HEAD",
        *args: Any,
        **kwargs: Any,
    ) -> Iterator["Submodule"]:
        try:
            pc = repo.commit(parent_commit)
            parser = cls._config_parser(repo, pc, read_only=True)
        except (IOError, BadName):
            return

        for sms in parser.sections():
            n = sm_name(sms)
            p = parser.get(sms, "path")
            u = parser.get(sms, "url")
            b = cls.k_head_default
            if parser.has_option(sms, cls.k_head_option):
                b = str(parser.get(sms, cls.k_head_option))

            index = repo.index
            try:
                rt = pc.tree
                sm = rt[p]
            except KeyError:
                try:
                    entry = index.entries[index.entry_key(p, 0)]
                    sm = Submodule(repo, entry.binsha, entry.mode, entry.path)
                except KeyError:
                    continue

            if type(sm) is not Submodule:
                continue

            sm._name = n
            if pc != repo.commit():
                sm._parent_commit = pc
            sm._branch_path = git.Head.to_full_path(b)
            sm._url = u

            yield sm

